# Q.3 — C program: Sum of Fibonacci numbers at even indexes up to N terms
(Assume indexing starts at 0: F0=0, F1=1. Sum Fibonacci terms whose index is even: i = 0,2,4,... among first N terms.)

```c
#include <stdio.h>

int main() {
    int N;
    printf("Enter number of terms N: ");
    if (scanf("%d", &N) != 1 || N <= 0) {
        printf("Enter a positive integer.\n");
        return 0;
    }

    long long sum = 0;
    long long a = 0, b = 1; // F0=0, F1=1

    for (int i = 0; i < N; ++i) {
        long long current = a;
        if (i % 2 == 0) sum += current;
        // next Fibonacci
        long long next = a + b;
        a = b;
        b = next;
    }

    printf("Sum of Fibonacci numbers at even indexes (first %d terms) = %lld\n", N, sum);
    return 0;
}
```

