# Q.4 a) — C++ program: Add two distances (feet & inches) using constructor overloading and a friend function

```cpp
#include <iostream>
using namespace std;

class Distance {
private:
    int feet;
    float inches;

public:
    // Default constructor
    Distance() : feet(0), inches(0.0f) {}

    // Parameterized constructor
    Distance(int f, float in) : feet(f), inches(in) { normalize(); }

    // Constructor with only inches
    Distance(float in) : feet(0), inches(in) { normalize(); }

    void normalize() {
        // Convert inches >= 12 into feet
        if (inches >= 12.0f) {
            feet += (int)(inches / 12);
            inches = fmod(inches, 12.0f);
        }
    }

    void display() const {
        cout << feet << " ft " << inches << " in\n";
    }

    friend Distance add(const Distance &d1, const Distance &d2);
};

Distance add(const Distance &d1, const Distance &d2) {
    Distance res;
    res.feet = d1.feet + d2.feet;
    res.inches = d1.inches + d2.inches;
    res.normalize();
    return res;
}

int main() {
    Distance d1(5, 8.5f);    // 5 ft 8.5 in
    Distance d2(3, 7.75f);   // 3 ft 7.75 in

    cout << "Distance 1: "; d1.display();
    cout << "Distance 2: "; d2.display();

    Distance sum = add(d1, d2);
    cout << "Sum: ";
    sum.display();
    return 0;
}
```

