# Q.5 b) — C++ program: Gross salary + Income Tax deduction + Net salary (using inheritance)

We create `Gross` (basic pay, HRA, DA, TA) and `Deduction` (PF, TDS). `Employee` inherits both and computes net salary.

```cpp
#include <iostream>
using namespace std;

class Gross {
protected:
    double basic, hra, da, ta;
public:
    void getdata() {
        cout << "Enter Basic Pay: "; cin >> basic;
        cout << "Enter HRA: "; cin >> hra;
        cout << "Enter DA: "; cin >> da;
        cout << "Enter TA: "; cin >> ta;
    }
    void displaydata() const {
        cout << "Basic: " << basic << "\nHRA: " << hra << "\nDA: " << da << "\nTA: " << ta << "\n";
    }
};

class Deduction {
protected:
    double pf, tds;
public:
    void getdata() {
        cout << "Enter PF deduction: "; cin >> pf;
        cout << "Enter TDS deduction: "; cin >> tds;
    }
    void displaydata() const {
        cout << "PF: " << pf << "\nTDS: " << tds << "\n";
    }
};

class Employee : public Gross, public Deduction {
public:
    void getAll() {
        cout << "----- Enter gross salary details -----\n";
        Gross::getdata();
        cout << "----- Enter deductions -----\n";
        Deduction::getdata();
    }

    void displayNet() {
        cout << "\n--- Salary Details ---\n";
        Gross::displaydata();
        Deduction::displaydata();
        double grossTotal = basic + hra + da + ta;
        double totalDeductions = pf + tds;
        double net = grossTotal - totalDeductions;
        cout << "Gross Salary: " << grossTotal << "\nTotal Deductions: " << totalDeductions
             << "\nNet Salary: " << net << "\n";
    }
};

int main() {
    Employee emp;
    emp.getAll();
    emp.displayNet();
    return 0;
}
```

**Type of inheritance used:** *Multiple inheritance* (`Employee` inherits from `Gross` and `Deduction`). This suits the problem because gross details and deduction details are stored in two separate classes.

