# ✅ **Super Simple Version (Best for Exams)**

```cpp
#include <iostream>
using namespace std;

class Distance {
private:
    int feet;
    int inches;

public:
    // Default constructor
    Distance() {
        feet = 0;
        inches = 0;
    }

    // Parameterized constructor
    Distance(int f, int in) {
        feet = f;
        inches = in;

        // convert inches to feet if >= 12
        if (inches >= 12) {
            feet += inches / 12;
            inches = inches % 12;
        }
    }

    // Friend function to add distances
    friend Distance add(Distance d1, Distance d2);

    void display() {
        cout << feet << " ft " << inches << " in" << endl;
    }
};

Distance add(Distance d1, Distance d2) {
    Distance temp;
    temp.feet = d1.feet + d2.feet;
    temp.inches = d1.inches + d2.inches;

    if (temp.inches >= 12) {
        temp.feet += temp.inches / 12;
        temp.inches = temp.inches % 12;
    }

    return temp;
}

int main() {
    Distance d1(5, 8);  // 5 ft 8 in
    Distance d2(3, 7);  // 3 ft 7 in

    cout << "Distance 1: ";
    d1.display();

    cout << "Distance 2: ";
    d2.display();

    Distance sum = add(d1, d2);

    cout << "Sum: ";
    sum.display();

    return 0;
}
```

