    }
    void display() override {
        cout << "Tape: " << title << " Price: " << price << " Time: " << time << " mins" << endl;
    }
};

int main() {
    Media *m1 = new Book;
    Media *m2 = new Tape;

    m1->getData();
    m2->getData();

    m1->display();
    m2->display();

    return 0;
}
